# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def _sort_key(student: Student) -> Tuple[str, str]:
    return (student.last_name.casefold(), student.first_name.casefold())

def _require_emails(ordered: List[Student]) -> None:
    for student in ordered:
        if not student.email:
            label = f"{student.display_name} (id {student.student_id})"
            raise ValueError(f"no email on file for {label}")

def _align_columns(ordered: List[Student]) -> List[str]:
    name_width = max(len(student.display_name) for student in ordered)
    section_width = max(len(student.section) for student in ordered)
    return [
        f"{student.display_name:<{name_width}}  "
        f"{student.section:<{section_width}}  {student.email}"
        for student in ordered
    ]

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Aligned name, section and email rows, sorted by name."""
    ordered = sorted(students, key=_sort_key)
    if not ordered:
        raise ValueError("no students to build a contact sheet from")
    _require_emails(ordered)
    return _align_columns(ordered)
